local config = {
  ui_story_5055_50550101_1_dialog_content = "Good morning, Eve!",
  ui_story_5055_50550101_2_dialog_content = "Huh? Let me see. What's up with your bloodshot eyes? Did you have a rough night's sleep or something?",
  ui_story_5055_50550101_3_dialog_content = "Sir? Please come in!",
  ui_story_5055_50550101_4_dialog_content = "Don't you live on Tail Street? Why did you come here?",
  ui_story_5055_50550101_5_dialog_content = "Is it because I haven't returned the book I borrowed from you? I'll finish it as fast as I can and trade you for other books!",
  ui_story_5055_50550101_6_dialog_content = "Hahaha, you're truly a studious and diligent kid, Eve.",
  ui_story_5055_50550101_7_dialog_content = "But I'm not here to talk about the book. Do you remember? You need to go back to your <color=#FFB400>doctor</color> today.",
  ui_story_5055_50550101_8_dialog_content = "Eh? Doctor...?",
  ui_story_5055_50550101_9_dialog_content = "Oh, no! I'm supposed to go to Tail Street today for the doctor?!",
  ui_story_5055_50550101_10_dialog_content = "What now? I-I overslept and forgot it completely... I'll go right now!",
  ui_story_5055_50550101_11_dialog_content = "Hahaha, no worries. I talked to the doctor before coming here, and you can go there in the afternoon.",
  ui_story_5055_50550101_12_dialog_content = "I made it tough on you and the doctor again...",
  ui_story_5055_50550101_13_dialog_content = "No need to be so formal with me. Seeing you're all right puts my mind at ease as well.",
  ui_story_5055_50550101_14_dialog_content = "Others thought it wasn't worth their time to deal with your recovery, given that you left with a lingering illness after being attacked by the Eclipsites.",
  ui_story_5055_50550101_15_dialog_content = "Only she, disregarding all the sneers and ridicule, persisted in providing treatment for you...",
  ui_story_5055_50550101_16_dialog_content = "And now, our little Eve has not only <color=#FFB400>fully recovered</color> but also mastered powerful Luminatics. Who knows, you might become a warrior protecting our realm one day.",
  ui_story_5055_50550101_17_dialog_content = "Your doctor and I are thrilled to see the changes in you. There's absolutely no reason for us to hold you accountable for this minor slip-up.",
  ui_story_5055_50550101_18_dialog_content = "I'm... recovered? And I've mastered powerful Luminatics on top of that?",
  ui_story_5055_50550101_19_dialog_content = "Hahaha, Eve, are you still half-asleep or what?",
  ui_story_5055_50550101_20_dialog_content = "Uh...",
  ui_story_5055_50550101_21_dialog_content = "If it weren't for you, who else would have safely escorted the caravan to return from the Hot Air Desert?",
  ui_story_5055_50550101_22_dialog_content = "And who else could rescue the children from the clutches of the Eclipsites? Oh, and—",
  ui_story_5055_50550101_23_dialog_content = "Say no more, sir. It's just a small effort on my part, not worthy of recognition.",
  ui_story_5055_50550101_24_dialog_content = "Oh, our little Eve has finally remembered everything now.",
  ui_story_5055_50550101_25_dialog_content = "Your doctor mentioned that if today's check-up goes well, she might send you to study in the <color=#FFB400>Illumina Federation</color>.",
  ui_story_5055_50550101_26_dialog_content = "Illumina Federation... is it where you were, sir?",
  ui_story_5055_50550101_27_dialog_content = "That's right. The Illumina Federation offers the most formal and rigorous education in knowledge and physical training.",
  ui_story_5055_50550101_28_dialog_content = "If you get the chance to study there, you'll surely become a great warrior, protecting the peace of this desert.",
  ui_story_5055_50550101_29_dialog_content = "I have faith in you. But hey, don't stress yourself out too much. Let's discuss this after your check-up results are out.",
  ui_story_5055_50550101_30_dialog_content = "Don't forget your appointment with the doctor this time. See you in the afternoon.",
  ui_story_5055_50550101_31_dialog_content = "Thank you, sir. See you this afternoon!",
  ui_story_5055_50550101_32_dialog_content = "Preserving peace for the whole desert... Can I really do that...",
  ui_story_5055_50550101_33_dialog_content = "Let's not get too far ahead of myself and start with what I can do now.",
  ui_story_5055_50550101_33X1_dialog_content = "Like, tidy up the room!",
  ui_story_5055_50550101_34_dialog_content = "Ha! Filthy dust, how dare you pile up in my room?",
  ui_story_5055_50550101_35_dialog_content = "The great warrior Eve will eradicate you, just you wait!",
  ui_story_5055_50550101_36_dialog_content = "And that goes for any of you Eclipsites lurking nearby too!",
  ui_story_5055_50550101_37_dialog_content = "You best stay out of Warrior Eve's way or you won't even live to regret it!",
  ui_story_5055_50550101_38_dialog_content = "Also... Right, I got a lot of help when I was sick, so...",
  ui_story_5055_50550101_39_dialog_content = "I'll repay them with my power and be a truly great warrior!",
  ui_story_5055_50550101_40_dialog_content = "Well, not that I really know how to be great.",
  ui_story_5055_50550101_41_dialog_content = "But my teacher just said my Luminatics was powerful, and I might have a chance to study in Illumina later.",
  ui_story_5055_50550101_42_dialog_content = "After I graduate, I'm sure I'll be a truly great warrior by then!",
  ui_story_5055_50550101_43_dialog_content = "Then my teacher, my doctor, Mom, Dad, and all the neighbors will be proud of me! Oh, and...",
  ui_story_5055_50550101_44_dialog_content = "...?",
  ui_story_5055_50550101_45_dialog_content = "And... I think I forgot someone <color=#FFB400>very important</color>... I...",
  ui_story_5055_50550101_46_dialog_content = "Ugh, my head hurts...",
  ui_story_5055_50550101_47_dialog_content = "What did I... forget?",
  ui_story_5055_50550101_48_dialog_content = "The more I try to remember, the more my head hurts...",
  ui_story_5055_50550101_49_dialog_content = "Don't.",
  ui_story_5055_50550101_50_dialog_content = "Huh?!",
  ui_story_5055_50550101_51_dialog_content = "Don't forget.",
  ui_story_5055_50550101_52_dialog_content = "Don't forget what? What do you know?",
  ui_story_5055_50550101_53_dialog_content = "...",
  ui_story_5055_50550101_54_dialog_content = "Wait, y-you're not my neighbor or a friend...",
  ui_story_5055_50550101_55_dialog_content = "Who are you?",
  ui_story_5055_50550101_56_dialog_content = "...",
  ui_story_5055_50550101_57_dialog_content = "Hey, stop!",
  ui_story_5055_50550102_1_dialog_content = "Huff, why would it run?",
  ui_story_5055_50550102_2_dialog_content = "That figure dropped something. It should be around here.",
  ui_story_5055_50550102_3_dialog_content = "Aha, found it!",
  ui_story_5055_50550102_4_dialog_content = "Weird, how come all the faces in this drawing are torn out?",
  ui_story_5055_50550102_5_dialog_content = "And the drawing looks so familiar... Did someone I know draw it?",
  ui_story_5055_50550102_6_dialog_content = "Hey, there's a name on the back of the sketchbook...",
  ui_story_5055_50550102_7_dialog_content = "<color=#FFB400>Eve</color>?!",
  ui_story_5055_50550102_8_dialog_content = "I-Is this my sketchbook?",
  ui_story_5055_50550102_9_dialog_content = "When did I draw this...?",
  ui_story_5055_50550102_10_dialog_content = "Too bad it's so badly torn.",
  ui_story_5055_50550102_11_dialog_content = "That figure... The figure must have destroyed the picture!",
  ui_story_5055_50550102_12_dialog_content = "Gotta hunt it down and find out... Can't let it get away!",
  ui_story_5055_50550501_1_dialog_content = "Huff, puff...",
  ui_story_5055_50550501_2_dialog_content = "Got ya!",
  ui_story_5055_50550501_3_dialog_content = "(This is weird... It looks like a bear doll.)",
  ui_story_5055_50550501_4_dialog_content = "(I have this feeling I've seen it somewhere before, but how come it looks so terrifying now... What a pity...)",
  ui_story_5055_50550501_5_dialog_content = "Who are you, and why did you rip my sketchbook?",
  ui_story_5055_50550501_6_dialog_content = "Not. Me.",
  ui_story_5055_50550501_7_dialog_content = "It wasn't you? Do you mean I did it and forgot?",
  ui_story_5055_50550501_8_dialog_content = "But even if you didn't damage the sketchbook, why did you take it and call Eclipsites to help you?",
  ui_story_5055_50550501_9_dialog_content = "No. Not. Me.",
  ui_story_5055_50550501_10_dialog_content = "Good children own up to their mistakes.",
  ui_story_5055_50550501_11_dialog_content = "If you don't tell me the truth, I can only...",
  ui_story_5055_50550501_12_dialog_content = "Take the kid gloves off!",
  ui_story_5055_50550501_13_dialog_content = "You're. Not. From here.",
  ui_story_5055_50550501_14_dialog_content = "You. Don't. Belong here.",
  ui_story_5055_50550501_15_dialog_content = "What? This is Rediesel Desert. I was born and raised here.",
  ui_story_5055_50550501_16_dialog_content = "Everybody here is my friend, so why would you say that?",
  ui_story_5055_50550501_17_dialog_content = "Don't you. See.",
  ui_story_5055_50550501_18_dialog_content = "Nothing. Nothing here.",
  ui_story_5055_50550501_19_dialog_content = "Wh-What are you doing?",
  ui_story_5055_50550501_20_dialog_content = "I'll shatter. All. This <color=#FFB400>illusion</color>!",
  ui_story_5055_50550502_1_dialog_content = "Eve.",
  ui_story_5055_50550502_2_dialog_content = "(It knows my name?)",
  ui_story_5055_50550502_3_dialog_content = "(What even weirder is... the doll could speak?)",
  ui_story_5055_50550502_4_dialog_content = "(It might be tainted by Darkflow, judging from how it looks.)",
  ui_story_5055_50550502_5_dialog_content = "(No, how could a doll be contaminated?)",
  ui_story_5055_50550502_6_dialog_content = "You're. Not. From here.",
  ui_story_5055_50550502_7_dialog_content = "You. Don't. Belong here.",
  ui_story_5055_50550502_8_dialog_content = "(And why would it say that?)",
  ui_story_5055_50550502_9_dialog_content = "(No matter what, anything that could summon Eclipsites can't be good. I must warn the neighbors about this...)",
  ui_story_5055_50550502_10_dialog_content = "(Hey, it just... vanished?)",
  ui_story_5055_50550502_11_dialog_content = "(Completely into thin air, like everything here never existed at all.)",
  ui_story_5055_50550502_12_dialog_content = "Is it all just my hallucination?",
  ui_story_5055_50550502_13_dialog_content = "Did the Eclipsites hit my head when they attacked back then? I can't quite remember now...",
  ui_story_5055_50550502_14_dialog_content = "Guess I'll ask the doctor about it in the follow-up this afternoon.",
  ui_story_5055_50550502_15_dialog_content = "If there is really an issue with my head, will I still be able to go to school in Illumina?",
  ui_story_5055_50550502_16_dialog_content = "The thought's freaking me out now...",
  ui_story_5055_50550502_17_dialog_content = "But I will face it head-on! Right!",
  ui_story_5055_50550502_18_dialog_content = "There's still time before the follow-up, and I'm thirsty from all this running. I ought to get some water from the well.",
  ui_story_5055_50550502_19_dialog_content = "I have to be more useful and take care of my home!",
  ui_story_5055_50550601_1_dialog_content = "Rediesel Desert is great except for the shortage of water. It's hard for normal plants to grow here.",
  ui_story_5055_50550601_2_dialog_content = "My teacher said some meadows and forests are thousands of years old outside the desert, as well as oceans with reefs and kelp!",
  ui_story_5055_50550601_3_dialog_content = "I wonder when I can get a glimpse of something that vibrant and lively?",
  ui_story_5055_50550601_4_dialog_content = "\"Obviously grew up in the desert, yet so intrigued about the plant outside\"... Even my teacher wondered where I got that interest.",
  ui_story_5055_50550601_5_dialog_content = "I don't actually know either. Maybe it just came naturally?",
  ui_story_5055_50550601_6_dialog_content = "Okay, the well should be...",
  ui_story_5055_50550601_7_dialog_content = "Here!",
  ui_story_5055_50550601_8_dialog_content = "Even though the lake by the house is pretty, it has salt water, so I gotta get drinking water from the well.",
  ui_story_5055_50550601_9_dialog_content = "It's almost time for the follow-up.",
  ui_story_5055_50550601_10_dialog_content = "I gotta make this fast!",
  ui_story_5055_50550601_11_dialog_content = "Oops!",
  ui_story_5055_50550601_12_dialog_content = "<color=#e8d9bb>THUNK!</color>",
  ui_story_5055_50550601_13_dialog_content = "<color=#e8d9bb>Eve trips over something, losing her balance and falling to the ground.</color>",
  ui_story_5055_50550601_14_dialog_content = "You...",
  ui_story_5055_50550601_15_dialog_content = "(It's that doll again! But didn't I defeat it? How did it come out of the well?)",
  ui_story_5055_50550601_16_dialog_content = "(Luckily, the fall actually saved me from going closer to the well, or it would get the drop on me.)",
  ui_story_5055_50550601_17_dialog_content = "You're... not... from here...",
  ui_story_5055_50550601_18_dialog_content = "You... don't... belong... here...",
  ui_story_5055_50550601_19_dialog_content = "It's not the same manner of speech... Is it a different doll then?",
  ui_story_5055_50550601_20_dialog_content = "I'll... take you... out of here...",
  ui_story_5055_50550601_21_dialog_content = "Oh no, can't let it keep summoning Eclipsites!",
  ui_story_5055_50550602_1_dialog_content = "Phew, that was tough... It could pop up somewhere else again though.",
  ui_story_5055_50550602_2_dialog_content = "But it's definitely not a hallucination. I must warn the neighbors for sure!",
  ui_story_5055_50550602_3_dialog_content = "Hey, what's this under my feet?",
  ui_story_5055_50550602_4_dialog_content = "A small grass?",
  ui_story_5055_50550602_5_dialog_content = "But this is the middle of a thoroughfare... How tenacious it must be to survive.",
  ui_story_5055_50550602_6_dialog_content = "But why are the roots exposed too, like someone kicked it over...?",
  ui_story_5055_50550602_7_dialog_content = "Not kicked over—I tripped over it!",
  ui_story_5055_50550602_8_dialog_content = "Oh, poor grass, were you warning me not to get close to the well?",
  ui_story_5055_50550602_9_dialog_content = "You're my savior, I see!",
  ui_story_5055_50550602_10_dialog_content = "But you don't look like a desert plant. Where are you from?",
  ui_story_5055_50550602_11_dialog_content = "Hmm, the white stuff on your head...",
  ui_story_5055_50550602_12_dialog_content = "Is... is it some kind of \"tumor\"?",
  ui_story_5055_50550602_13_dialog_content = "You'll dry out and die trying to grow without a shade here.",
  ui_story_5055_50550602_14_dialog_content = "But if you don't mind, I'll take you home and feed you refreshing well water!",
  ui_story_5055_50550602_15_dialog_content = "Until then, make yourself comfortable in my pocket.",
  ui_story_5055_50550701_3_dialog_content = "By the way, the sun is ruthless today.",
  ui_story_5055_50550701_4_dialog_content = "Whoa!",
  ui_story_5055_50550701_5_dialog_content = "When and where did such a big thing come from?!",
  ui_story_5055_50550701_6_dialog_content = "It's... a giant lizard made out of steel bars and sheets?",
  ui_story_5055_50550701_8_dialog_content = "Could it be an ancient relic dug up out of the sand by one of the neighbors?",
  ui_story_5055_50550701_9_dialog_content = "Or is it a novelty invented by Illumina?",
  ui_story_5055_50550701_11_dialog_content = "Watch out! Stay away from that heap of trash!",
  ui_story_5055_50550701_12_dialog_content = "What? Trash?",
  ui_story_5055_50550701_13_dialog_content = "Yeah, it's just a bunch of worthless scrap—no clue who dumped this crap here.",
  ui_story_5055_50550701_14_dialog_content = "Besides taking up space, it's also attracting a bunch of <color=#FFB400>dangerous things</color> lurking inside, forcing us to patrol around here every day.",
  ui_story_5055_50550701_15_dialog_content = "Dangerous things? Let me get rid of it then!",
  ui_story_5055_50550701_16_dialog_content = "You worked hard. I just got water from the well... Here, have some and take a breath. I got this!",
  ui_story_5055_50550701_20_dialog_content = "...",
  ui_story_5055_50550701_21_dialog_content = "What? Another identical doll?",
  ui_story_5055_50550701_22_dialog_content = "Is this bear doll the danger you mentioned?",
  ui_story_5055_50550701_23_dialog_content = "Huh? What are you talking about? A doll? Where is it?",
  ui_story_5055_50550701_24_dialog_content = "What? But... Don't tell me only I can see it!",
  ui_story_5055_50550701_25_dialog_content = "...",
  ui_story_5055_50550701_26_dialog_content = "Anyway, please step back. This doll summons Eclipsites.",
  ui_story_5055_50550701_27_dialog_content = "I need to get rid of it first!",
  ui_story_5055_50550702_1_dialog_content = "...",
  ui_story_5055_50550702_2_dialog_content = "Why do dolls like this keep showing up today...? Or maybe they're following me?",
  ui_story_5055_50550702_3_dialog_content = "No!!! That thing showed up! We got some serious danger up in here!",
  ui_story_5055_50550702_4_dialog_content = "What? Where?",
  ui_story_5055_50550702_5_dialog_content = "Woof—woof! Woof, woof, woof!!",
  ui_story_5055_50550702_6_dialog_content = "Uh, that's just a dog.",
  ui_story_5055_50550702_7_dialog_content = "This is no ordinary dog. Look at how fierce it is, with its front limbs modified to be powerful and robust...",
  ui_story_5055_50550702_8_dialog_content = "And those scars all over its body... No way they're from dog fights—they're definitely marks left from battles with others like us!",
  ui_story_5055_50550702_9_dialog_content = "No one could possibly bear attacks from this dog! So we gotta...",
  ui_story_5055_50550702_10_dialog_content = "... Huh?",
  ui_story_5055_50550702_11_dialog_content = "Spin!",
  ui_story_5055_50550702_12_dialog_content = "Woof!",
  ui_story_5055_50550702_13_dialog_content = "Shake hand!",
  ui_story_5055_50550702_14_dialog_content = "Woof!",
  ui_story_5055_50550702_15_dialog_content = "You understand what I'm saying? What a smart dog! Let me scratch your ears!",
  ui_story_5055_50550702_16_dialog_content = "*whines*...",
  ui_story_5055_50550702_17_dialog_content = "Uhh...",
  ui_story_5055_50550702_18_dialog_content = "Hahaha! The dog that nobody could tame, yet you managed to bring it under control. You're really something, Eve!",
  ui_story_5055_50550702_19_dialog_content = "Animals rarely attack if we don't threaten them first.",
  ui_story_5055_50550702_20_dialog_content = "The puppy can feel it if we mean it no harm.",
  ui_story_5055_50550702_21_dialog_content = "It wasn't up to it whether to undergo the modifications...",
  ui_story_5055_50550702_22_dialog_content = "It acted mean probably because it was trying to protect itself and the pack.",
  ui_story_5055_50550702_23_dialog_content = "*whines*...",
  ui_story_5055_50550702_24_dialog_content = "Hahaha, it tickles when you lick my hand like that...",
  ui_story_5055_50550702_25_dialog_content = "See, it's a nice dog, and it knows what we're saying!",
  ui_story_5055_50550702_26_dialog_content = "*sigh* It seems like we were overly cautious, huh?",
  ui_story_5055_50550702_27_dialog_content = "I'll tell everyone about this immediately so they don't accidentally harm it.",
  ui_story_5055_50550702_28_dialog_content = "Okay, doggy, you're safe now. Nobody will try to drive you away.",
  ui_story_5055_50550702_29_dialog_content = "But you have to promise me not to hurt anyone.",
  ui_story_5055_50550702_30_dialog_content = "Hmmm, you can tell which house I live in by smell, right?",
  ui_story_5055_50550702_31_dialog_content = "If you can't find anything to eat, come see me, okay?",
  ui_story_5055_50550702_32_dialog_content = "Woof!",
  ui_story_5055_50550702_33_dialog_content = "Oops, I'm gonna be late for the follow-up with doc...",
  ui_story_5055_50550702_34_dialog_content = "Okay, you just hang out and I'll see you soon!",
  ui_story_5055_50550702_35_dialog_content = "*whimper*",
  ui_story_5055_50550702_36_dialog_content = "Hey, why are you clinging to my shoe like you don't want me to go?",
  ui_story_5055_50550702_37_dialog_content = "*whimper and bark*",
  ui_story_5055_50550702_38_dialog_content = "Okay, okay, I really got something very important to do right now.",
  ui_story_5055_50550702_39_dialog_content = "I promise you I'll come back for you, and we can even patrol together!",
  ui_story_5055_50550702_40_dialog_content = "*keeps whimpering*",
  ui_story_5055_50550801_1_dialog_content = "(What a poor puppy that was. Probably nobody wanted to get close before, or it wouldn't be so clingy.)",
  ui_story_5055_50550801_2_dialog_content = "(It wouldn't wait back there for me, and I can't bring it to the doctor...)",
  ui_story_5055_50550801_3_dialog_content = "(So I had to take the long way to lose it.)",
  ui_story_5055_50550801_4_dialog_content = "(I feel bad about it, but it has a keen nose and will probably catch up soon enough.)",
  ui_story_5055_50550801_5_dialog_content = "(I gotta finish the health check before then.)",
  ui_story_5055_50550801_6_dialog_content = "No! Help!",
  ui_story_5055_50550801_7_dialog_content = "The doctor's clinic is on fire! We need help! Now!",
  ui_story_5055_50550801_8_dialog_content = "What?!",
  ui_story_5055_50550801_9_dialog_content = "Doctor, professor, where are you?",
  ui_story_5055_50550801_10_dialog_content = "<size=45>Doctor? Professor? Can you hear me?</size>",
  ui_story_5055_50550801_11_dialog_content = "Somebody help us!",
  ui_story_5055_50550801_12_dialog_content = "Someone's still inside!",
  ui_story_5055_50550801_13_dialog_content = "I have to go in!",
  ui_story_5055_50550801_14_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5055_50550801_15_dialog_content = "... Please! Somebody!",
  ui_story_5055_50550801_16_dialog_content = "Professor, it's me, Eve! Where are you?",
  ui_story_5055_50550801_17_dialog_content = "...",
  ui_story_5055_50550801_18_dialog_content = "What? It's here too?",
  ui_story_5055_50550802_1_dialog_content = "Are you okay, sir?",
  ui_story_5055_50550802_2_dialog_content = "D-Don't come any closer!",
  ui_story_5055_50550802_3_dialog_content = "Sir? It's me, Eve, I'm here to get you out.",
  ui_story_5055_50550802_4_dialog_content = "Don't... Help! Help!",
  ui_story_5055_50550802_5_dialog_content = "My teacher had never panicked like this before... Must have been freaked out by that bear doll.",
  ui_story_5055_50550802_6_dialog_content = "And where's the doctor...?",
  ui_story_5055_50550802_7_dialog_content = "It was all her idea! Not mine! NOT MINE!",
  ui_story_5055_50550802_8_dialog_content = "Please don't hurt me—!",
  ui_story_5055_50550802_9_dialog_content = "Take it easy, sir. I'm Eve, your student. I'll never hurt you!",
  ui_story_5055_50550802_10_dialog_content = "Was someone trying to hurt you? Did the person set the clinic on fire too?",
  ui_story_5055_50550802_11_dialog_content = "It was you...",
  ui_story_5055_50550802_12_dialog_content = "Huh?",
  ui_story_5055_50550802_13_dialog_content = "It was you, you monster, who set fire to this place!",
  ui_story_5055_50550802_14_dialog_content = "What...?",
  ui_story_5055_50550802_15_dialog_content = "<color=#e8d9bb>*snaps and crackles*</color>",
  ui_story_5055_50550802_16_dialog_content = "(Fire... It's so hot...)",
  ui_story_5055_50550802_17_dialog_content = "(Where have I seen this... before...)",
  ui_story_5055_50550802_18_dialog_content = "(The same... fire...)",
  ui_story_5055_50550802_19_dialog_content = "(The ceiling's falling... Everything is sung all around... Too much smoke to breathe...)",
  ui_story_5055_50550802_20_dialog_content = "(There's someone... in the fire...)",
  ui_story_5055_50550802_21_dialog_content = "(Someone I'll never forget...)",
  ui_story_5055_50550802_22_dialog_content = "(She is...)",
  ui_story_5055_50550802_23_dialog_content = "(She is...!)",
  ui_story_5055_50550802_24_dialog_content = "It's you! I can't believe you came back.",
  ui_story_5055_50550802_25_dialog_content = "I'm here to save you, Doctor...",
  ui_story_5055_50550802_26_dialog_content = "Was it you who set fire to this place and ruined everything I've worked so hard to build up?",
  ui_story_5055_50550802_27_dialog_content = "No...",
  ui_story_5055_50550802_28_dialog_content = "I granted you better powers, but what have you done? Look at the mess you've made!",
  ui_story_5055_50550802_29_dialog_content = "My research, my data, everything I've built up over all these years... and even this very body, all consumed by the flames.",
  ui_story_5055_50550802_30_dialog_content = "Tell me, Eve—the sin of destroying me! What are you going to pay for that?",
  ui_story_5055_50550802_31_dialog_content = "<color=#e8d9bb>Bang! *Crackles*</color>",
  ui_story_5055_50550802_32_dialog_content = "It's not me, it's not me!",
  ui_story_5055_50550802_33_dialog_content = "Fire...! But I remember the fire, burning like undying hatred...",
  ui_story_5055_50550802_34_dialog_content = "Why did the fire happen, why would there be hatred in me?",
  ui_story_5055_50550802_35_dialog_content = "I just came here for a follow-up...",
  ui_story_5055_50550802_36_dialog_content = "I don't want to hurt anyone... I just want to be the Eve who protects everybody!",
  ui_story_5055_50550802_37_dialog_content = "Heheh... Hahahaha!",
  ui_story_5055_50550802_38_dialog_content = "Got no guts to admit it, huh? Weren't you the self-proclaimed perfect little angel?",
  ui_story_5055_50550802_39_dialog_content = "Fine then, You shall be buried together with my research data!",
  ui_story_5055_50550802_40_dialog_content = "Woof!",
  ui_story_5055_50550802_41_dialog_content = "The red doggy?",
  ui_story_5055_50550802_42_dialog_content = "No, don't come close... It's too dangerous, stay away!",
  ui_story_5055_50550802_43_dialog_content = "Bow-wow!",
  ui_story_5055_50550802_44_dialog_content = "Hahaha, another one who can't wait to meet their doom, huh?",
  ui_story_5055_50550802_45_dialog_content = "Alright! Bring it on! I'm just itching to test out this dagger!",
  ui_story_5055_50550802_46_dialog_content = "Awooo!!!",
  ui_story_5055_50550802_47_dialog_content = "What?!",
  ui_story_5055_50550802_48_dialog_content = "The building's collapsing... Watch out!",
  ui_story_5055_50550802_49_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5055_50550802_50_dialog_content = "(Am I buried under the collapsed building?)",
  ui_story_5055_50550802_51_dialog_content = "(Don't hear the doctor and the dog anymore, just the noise of flames devouring everything.)",
  ui_story_5055_50550802_52_dialog_content = "But I'm still breathing...",
  ui_story_5055_50550802_53_dialog_content = "I'm... still alive?",
  ui_story_5055_50550802_54_dialog_content = "Where did these vines come from, and why were they around me?",
  ui_story_5055_50550802_55_dialog_content = "There's a scent different from burnt. It's actually distinct and delightful.",
  ui_story_5055_50550802_56_dialog_content = "It's a pleasant scent... Smells like... flowers?",
  ui_story_5055_50550802_57_dialog_content = "I remember now. The thin, delicate white stuff outside the vines are flowers!",
  ui_story_5055_50550802_58_dialog_content = "Is it you, the grass with tumors in my pocket?",
  ui_story_5055_50550802_59_dialog_content = "That white bulb wasn't a tumor but a bud... How come I didn't recognize it?",
  ui_story_5055_50550802_60_dialog_content = "Thank you for saving me again.",
  ui_story_5055_50550802_61_dialog_content = "But what about the professor, doctor, and the red puppy...?",
  ui_story_5055_50550802_62_dialog_content = "Was it because of me...?",
  ui_story_5055_50550802_63_dialog_content = "<color=#e8d9bb>Boom!!!</color>",
  ui_story_5055_50550802_64_dialog_content = "Grass, no! Don't leave me... Don't...",
  ui_story_5055_50550802_65_dialog_content = "You fool, why would you sacrifice yourself to save me from the burning fire and crumbling building?",
  ui_story_5055_50550802_66_dialog_content = "If you stayed in my pocket, you would probably make it and root yourself in the ashen soil...",
  ui_story_5055_50550802_67_dialog_content = "Am I really worth the sacrifice?",
  ui_story_5055_50550802_68_dialog_content = "...",
  ui_story_5055_50550802_69_dialog_content = "Who's there?",
  ui_story_5055_50550802_70_dialog_content = "?!!",
  ui_story_5055_50550802_71_dialog_content = "Was it you who set fire to this place and ruined everything I've worked so hard to build up?",
  ui_story_5055_50550802_72_dialog_content = "It was you, you monster, who set fire to this place!",
  ui_story_5055_50550802_73_dialog_content = "Did you... set the fire?",
  ui_story_5055_50550802_74_dialog_content = "Yes.",
  ui_story_5055_50550802_75_dialog_content = "Who are you? How come you looked like me?",
  ui_story_5055_50550802_76_dialog_content = "I am you.",
  ui_story_5055_50550802_77_dialog_content = "I'm the pain you hid away, the fear you couldn't face, the memory you refused to recall.",
  ui_story_5055_50550802_78_dialog_content = "I'm here to tell you don't ignore...",
  ui_story_5055_50550802_79_dialog_content = "Don't ignore reality.",
  ui_story_5055_50551102_1_dialog_content = "I never knew there was a place like this on Tail Street.",
  ui_story_5055_50551102_2_dialog_content = "What?",
  ui_story_5055_50551102_3_dialog_content = "There... Why is that girl being held there?",
  ui_story_5055_50551102_4_dialog_content = "So many tubes and instruments hooked up to her body... What a poor thing! Won't someone save her?",
  ui_story_5055_50551102_5_dialog_content = "That's not a cell but a treatment room to keep her and everyone around her safe.",
  ui_story_5055_50551102_6_dialog_content = "Treatment room? And I see a bear doll inside!",
  ui_story_5055_50551102_7_dialog_content = "It's her favorite toy and most loyal companion.",
  ui_story_5055_50551102_8_dialog_content = "As for the girl, no one knows her better than you.",
  ui_story_5055_50551102_9_dialog_content = "I know her? She seems so weak, vapid, and her face...",
  ui_story_5055_50551102_10_dialog_content = "Looks the same as yours!",
  ui_story_5055_50551102_11_dialog_content = "And mine, too!",
  ui_story_5055_50551102_12_dialog_content = "That's the real Eve, the Eve in the real world.",
  ui_story_5055_50551102_13_dialog_content = "The real Eve? You mean you and I are fakes?",
  ui_story_5055_50551102_14_dialog_content = "We are not fake. What's fake is the world we're in right now.",
  ui_story_5055_50551102_15_dialog_content = "This is the bogus world doctor created for us through hypnotism, a world of false happiness.",
  ui_story_5055_50551102_16_dialog_content = "She deceived us from the start. She never wanted to treat us.",
  ui_story_5055_50551102_17_dialog_content = "She removed the excess personalities in our memory that would threaten her experiment.",
  ui_story_5055_50551102_18_dialog_content = "Then she rewrote the history for us, where our parents are alive, we're healed, healthy, and live happily ever after.",
  ui_story_5055_50551102_19_dialog_content = "All to keep us sane while she performed all sorts of immoral experiments on us.",
  ui_story_5055_50551102_20_dialog_content = "...",
  ui_story_5055_50551102_21_dialog_content = "Even though we left the doctor behind eventually...",
  ui_story_5055_50551102_22_dialog_content = "This world still controls us, keeping us from seeing the real world.",
  ui_story_5055_50551102_23_dialog_content = "I'm very happy living in this world... So even the joy is not real?",
  ui_story_5055_50551102_24_dialog_content = "I know you've forgotten your unbearable past, and that's a good thing from certain perspectives.",
  ui_story_5055_50551102_25_dialog_content = "But you can't stay here. We must go back to the real world.",
  ui_story_5055_50551102_26_dialog_content = "Go back...?",
  ui_story_5055_50551102_27_dialog_content = "But I don't want to. I just want to draw, water the grass, patrol outside the village, and protect everybody...",
  ui_story_5055_50551102_28_dialog_content = "Why lock me up like this? I don't want it, I don't want it!",
  ui_story_5055_50551102_29_dialog_content = "But you must stay in there or you'll destroy everything!",
  ui_story_5055_50551102_30_dialog_content = "Do you want a repeat of the tragedy that happened to your hometown?",
  ui_story_5055_50551102_31_dialog_content = "Tragedy, hometown? What do you mean?",
  ui_story_5055_50551102_32_dialog_content = "Do you want to see your loved ones get hurt by you again?",
  ui_story_5055_50551102_33_dialog_content = "Brother, and Dawn.",
  ui_story_5055_50551102_34_dialog_content = "Brother? I have a brother? Dawn...?",
  ui_story_5055_50551102_35_dialog_content = "Ugh, my head's hurting again!",
  ui_story_5055_50551102_36_dialog_content = "I see you still can't remember.",
  ui_story_5055_50551102_37_dialog_content = "Unlike you, I never assimilated into this world, so I still remember everything we went through.",
  ui_story_5055_50551102_38_dialog_content = "They are all we have.",
  ui_story_5055_50551102_39_dialog_content = "But we're trapped in this bogus world, unable to see those who truly loved us.",
  ui_story_5055_50551102_40_dialog_content = "So I hate the doctor who erased them... And hate you as well!",
  ui_story_5055_50551102_41_dialog_content = "I hate you for forgetting they ever existed and accepting this fake reality in complete ignorance.",
  ui_story_5055_50551102_42_dialog_content = "!!!",
  ui_story_5055_50551102_43_dialog_content = "I see I have to make you remember everything to convince you.",
  ui_story_5055_50551102_44_dialog_content = "Well, follow me to our hometown then.",
  ui_story_5055_50551102_45_dialog_content = "The one we destroyed with our own hands.",
  ui_story_5055_50551102_46_dialog_content = "Hometown... But isn't this it?",
  ui_story_5055_50551102_47_dialog_content = "Follow me.",
  ui_story_5055_50551301_1_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5055_50551301_2_dialog_content = "Hey, did a volcano just erupt?",
  ui_story_5055_50551301_3_dialog_content = "The hot stuff rolling all over the ground is lava, right?",
  ui_story_5055_50551301_4_dialog_content = "I can feel one heat wave after another, even from here.",
  ui_story_5055_50551301_5_dialog_content = "Are we still going?",
  ui_story_5055_50551301_6_dialog_content = "We're almost there, our home.",
  ui_story_5055_50551301_7_dialog_content = "Is our home inside the volcano?",
  ui_story_5055_50551301_8_dialog_content = "I'll wait for you over there.",
  ui_story_5055_50551301_9_dialog_content = "Hey, wait for me!",
  ui_story_5055_50551301_10_dialog_content = "Graah!!",
  ui_story_5055_50551301_11_dialog_content = "There are Eclipsites even in such a hostile environment?",
  ui_story_5055_50551301_12_dialog_content = "These Eclipsites... They are reminding me of something...",
  ui_story_5055_50551301_13_dialog_content = "The day when they invaded the village and razed it down to the ground...",
  ui_story_5055_50551301_14_dialog_content = "And the day when I got the monstrous power and rampaged like they did.",
  ui_story_5055_50551301_15_dialog_content = "The Darkflow entered my body through a tiny seed...",
  ui_story_5055_50551301_16_dialog_content = "I felt hot and numb inside, like a hundred stars exploding in silence.",
  ui_story_5055_50551301_17_dialog_content = "I wanted to lose that tormenting power only to realize it picked me up off the ground!",
  ui_story_5055_50551301_18_dialog_content = "I freaked out when I hovered in mid-air. All I wanted was to grab and hold on to something.",
  ui_story_5055_50551301_19_dialog_content = "I ended up grabbing telluric current.",
  ui_story_5055_50551301_20_dialog_content = "I disrupted the magnetic field, injected energy into the crust, made the volcano erupt, and turned home into this...",
  ui_story_5055_50551301_21_dialog_content = "The monstrous power enslaved me at my weakest, most helpless moment!",
  ui_story_5055_50551301_22_dialog_content = "I lost all reasoning like them and destroyed everything without remorse...",
  ui_story_5055_50551301_23_dialog_content = "Do I deserve to live on like this?",
  ui_story_5055_50551402_1_dialog_content = "Huff, huff...",
  ui_story_5055_50551402_2_dialog_content = "It's getting harder... and harder... to breathe...",
  ui_story_5055_50551402_3_dialog_content = "Why do I have to... fight Eclipsites under this condition...?",
  ui_story_5055_50551402_4_dialog_content = "I'm not far enough that I can't turn back.",
  ui_story_5055_50551402_5_dialog_content = "But...",
  ui_story_5055_50551402_6_dialog_content = "Should I turn back?",
  ui_story_5055_50551402_7_dialog_content = "Even this happy timeline has been shattered by flame.",
  ui_story_5055_50551402_8_dialog_content = "That other me said no one expected me to be an excellent warrior in reality.",
  ui_story_5055_50551402_9_dialog_content = "The doctor was just using my body but I unleashed unbridled vengeance on her.",
  ui_story_5055_50551402_10_dialog_content = "Is this the prospect I must face?",
  ui_story_5055_50551402_11_dialog_content = "Returning to an unfortunate reality, full of hatred and pain, enduring the loneliness and torment of confinement.",
  ui_story_5055_50551402_12_dialog_content = "What if I lose control again...?",
  ui_story_5055_50551402_13_dialog_content = "I might hurt even more people and turn the surrounding into an inferno like this...",
  ui_story_5055_50551402_14_dialog_content = "No, I absolutely must not allow that to happen.",
  ui_story_5055_50551402_15_dialog_content = "If that's true nature, I must avoid it somehow!",
  ui_story_5055_50551801_1_dialog_content = "Huff, huff...",
  ui_story_5055_50551801_2_dialog_content = "Here you are. This is our hometown...",
  ui_story_5055_50551801_3_dialog_content = "Red-Eye Gorge.",
  ui_story_5055_50551801_4_dialog_content = "Finally, you remembered.",
  ui_story_5055_50551801_5_dialog_content = "As soon as I set foot here, the past flooded back to me in bubble-like fragments, popping up one by one in my mind.",
  ui_story_5055_50551801_6_dialog_content = "I finally realized those scary flashes of vision that came to me were all real.",
  ui_story_5055_50551801_7_dialog_content = "This was once a self-sufficient settlement, but only loose rocks and charred soils remained now...",
  ui_story_5055_50551801_8_dialog_content = "Bursting lava, overcasting ashes, broken earth... All because of me.",
  ui_story_5055_50551801_9_dialog_content = "It's this way all because of me.",
  ui_story_5055_50551801_10_dialog_content = "Maybe it's better for me to stay here forever.",
  ui_story_5055_50551801_11_dialog_content = "...",
  ui_story_5055_50551801_12_dialog_content = "You want me to go back to the real world, right?",
  ui_story_5055_50551801_13_dialog_content = "But you also know I'll likely cause more trouble for those around me.",
  ui_story_5055_50551801_14_dialog_content = "So is it better for me to stay? That way, the real me will never wake up and never lose control...",
  ui_story_5055_50551801_15_dialog_content = "If we don't go back, there's no chance of leaving the treatment room.",
  ui_story_5055_50551801_16_dialog_content = "But I can't control myself...",
  ui_story_5055_50551801_17_dialog_content = "Not in the past, not now, and probably not in the future, either...",
  ui_story_5055_50551801_18_dialog_content = "I can accept the helplessness and endure those horrific memories...",
  ui_story_5055_50551801_19_dialog_content = "But I cannot let people who loved me get hurt over and over again!",
  ui_story_5055_50551801_20_dialog_content = "If you give up, that will still hurt those who loved us.",
  ui_story_5055_50551801_21_dialog_content = "We must go back.",
  ui_story_5055_50551801_22_dialog_content = "It's even harder to face harsh reality after waking up from a sweet dream.",
  ui_story_5055_50551801_23_dialog_content = "I don't have what it takes to withstand all that shock at once...",
  ui_story_5055_50551801_24_dialog_content = "But I must thank you for telling me my true reality and letting me know there are still people who genuinely love me.",
  ui_story_5055_50551801_25_dialog_content = "But I... just can't go back with you.",
  ui_story_5055_50551801_26_dialog_content = "Yes, you can. We can.",
  ui_story_5055_50551801_27_dialog_content = "If that's what you insist, my only choice is...",
  ui_story_5055_50551801_28_dialog_content = "To destroy you!",
  ui_story_5055_50551801_29_dialog_content = "You're the only key for me to return to reality. I can lock myself up here forever if I get rid of you.",
  ui_story_5055_50551801_30_dialog_content = "Killing me and you'll never see those who love us again.",
  ui_story_5055_50551801_31_dialog_content = "Even though my brother, Dawn, and others aren't here, it's all right. I don't need anyone.",
  ui_story_5055_50551801_32_dialog_content = "I'm ready to be alone.",
  ui_story_5055_50551801_33_dialog_content = "That's far better than losing my mind and obliterating everything I love with my own hand...",
  ui_story_5055_50551801_34_dialog_content = "A dangerous threat like me should stay asleep and not wake up.",
  ui_story_5055_50551801_35_dialog_content = "I know you mean well. Thank you, but sorry.",
  ui_story_5055_50551801_36_dialog_content = "I must kill you.",
  ui_story_5055_50551801_37_dialog_content = "I am you. You'll lose your power by killing me, and you in reality will probably die.",
  ui_story_5055_50551801_38_dialog_content = "Is that so? Isn't that even better, though?",
  ui_story_5055_50551801_39_dialog_content = "I've grown very weary of this...",
  ui_story_5055_50551801_40_dialog_content = "Now, let's end it.",
  ui_story_5055_50551802_1_dialog_content = "End it, end everything.",
  ui_story_5055_50551802_2_dialog_content = "The lava stopped flowing. The black smoke paused in mid-air. Even the Eclipsites nearby halted...",
  ui_story_5055_50551802_3_dialog_content = "It's so quiet.",
  ui_story_5055_50551802_4_dialog_content = "Enough to hear my heartbeat.",
  ui_story_5055_50551802_5_dialog_content = "But my heart should stop beating soon enough.",
  ui_story_5055_50551802_6_dialog_content = "Hey, I hear a sound, the sound of something bursting...",
  ui_story_5055_50551802_7_dialog_content = "It's the memory bubbles bursting in my head.",
  ui_story_5055_50551802_8_dialog_content = "No more fear, no more sorrow, and no more pain...",
  ui_story_5055_50551802_9_dialog_content = "But why? Why do the tears flow nonstop?",
  ui_story_5055_50551802_10_dialog_content = "The dull ache in my chest... Is it from the power leaving me?",
  ui_story_5055_50551802_11_dialog_content = "Or is it what they called longing...?",
  ui_story_5055_50551802_12_dialog_content = "Brother, Dawn... I still fail to recall your faces in the end.",
  ui_story_5055_50551802_13_dialog_content = "But I miss you so much, and the others too...",
  ui_story_5055_50551802_14_dialog_content = "Don't you think I'm crying because I don't want to leave you. I-I'm crying because...",
  ui_story_5055_50551802_15_dialog_content = "Of joy! Finally, I protected all of you in my own way!",
  ui_story_5055_50551802_16_dialog_content = "See, I didn't forget about joy. Joy does bring tears, too.",
  ui_story_5055_50551802_17_dialog_content = "I hope everyone will feel happy for me...",
  ui_story_5055_50551802_18_dialog_content = "At last, I can leave painlessly, quietly, silently...",
  ui_story_5055_50551802_19_dialog_content = "This is the best way I can think of to reciprocate your love.",
  ui_story_5055_50551802_20_dialog_content = "...",
  ui_story_5055_50551802_21_dialog_content = "<color=#e8d9bb>*rumbles*</color>",
  ui_story_5055_50551802_22_dialog_content = "What's going on?",
  ui_story_5055_50551802_23_dialog_content = "<size=45><color=#e8d9bb>Rumbling!</color></size>",
  ui_story_5055_50551802_24_dialog_content = "Everything is vanishing, even my power, so nothing shouldn't be affecting this reality...",
  ui_story_5055_50551802_25_dialog_content = "Unless...",
  ui_story_5055_50551802_26_dialog_content = "Unless the real me is dying.",
  ui_story_5055_50551802_27_dialog_content = "Don't try to waste your effort trying to save me, please...",
  ui_story_5055_50551802_28_dialog_content = "Just let me go...",
  ui_story_5055_50551802_29_dialog_content = "No, you're still alive and you must live!",
  ui_story_5055_50551802_30_dialog_content = "Who is this?",
  ui_story_5055_50551802_31_dialog_content = "Don't you remember me, Eve? It's PlayerName. I'm PlayerName!",
  ui_story_5055_50551802_32_dialog_content = "PlayerName? I've heard the story of Prince Pharming saving a comatose princess... Are you my Prince Charming?",
  ui_story_5055_50551802_33_dialog_content = "But you don't have to bring up my past, because even I know...",
  ui_story_5055_50551802_34_dialog_content = "Someone like me is not worth saving...",
  ui_story_5055_50551802_35_dialog_content = "But we really need your help!",
  ui_story_5055_50551802_36_dialog_content = "My help? What can I do?",
  ui_story_5055_50551802_37_dialog_content = "You can do more than you imagined!",
  ui_story_5055_50551802_38_dialog_content = "But my power is evil and uncontrollable. I'll destroy everything...",
  ui_story_5055_50551802_39_dialog_content = "Neither the doctor nor Eclipsites forced that on you!",
  ui_story_5055_50551802_40_dialog_content = "It is your natural ability that's been dormant inside you!",
  ui_story_5055_50551802_41_dialog_content = "It is strong enough to protect us all!",
  ui_story_5055_50551802_42_dialog_content = "Remember the true source of your power!",
  ui_story_5055_50551802_43_dialog_content = "We'll all waiting for you to come back...",
  ui_story_5055_50551802_44_dialog_content = "<size=45>Wake up!</size>",
  ui_story_5055_50551802_45_dialog_content = "<size=45>Wake up!</size> WAKE UP! <size=30>Wake up...</size>",
  ui_story_5055_50551901_1_dialog_content = "...",
  ui_story_5055_50551901_2_dialog_content = "Got it... I finally found the lost piece!",
  ui_story_5055_50551901_3_dialog_content = "These are the people most important to me...",
  ui_story_5055_50551901_4_dialog_content = "Now it's time to put everyone's portraits together!",
  ui_story_5055_50551901_5_dialog_content = "Can this be...",
  ui_story_5055_50551901_6_dialog_content = "Hmm, it's worth a try.",
  ui_story_5055_50551901_7_dialog_content = "...",
  ui_story_5055_50551901_8_dialog_content = "Hey, this is...",
  ui_story_5055_50551901_9_dialog_content = "Sinsa... Dawn... PlayerName...!",
  ui_story_5055_50551901_10_dialog_content = "All of their faces! I finally remember what they all look like.",
  ui_story_5055_50551901_11_dialog_content = "What's going on, why can't I control my tears today...",
  ui_story_5055_50551901_12_dialog_content = "I see I actually wanted to see everyone more than I believed.",
  ui_story_5055_50551901_13_dialog_content = "I thought I'd made up my mind to stay here once and for all...",
  ui_story_5055_50551901_14_dialog_content = "No, you wanted to get out, wake up, and go for a walk in your best outfit.",
  ui_story_5055_50551901_15_dialog_content = "You can visit a prairie teeming with flowers, or a lush rainforest.",
  ui_story_5055_50551901_16_dialog_content = "I thought my power had turned me into a monster that would only hurt people...",
  ui_story_5055_50551901_17_dialog_content = "No, you'll protect us with your power.",
  ui_story_5055_50551901_18_dialog_content = "As long as you trust the person you can become. Her greatness and glory will be your future.",
  ui_story_5055_50551901_19_dialog_content = "I thought if I stayed away from everyone and was alone, I won't cause any trouble...",
  ui_story_5055_50551901_20_dialog_content = "No, you were never alone.",
  ui_story_5055_50551901_21_dialog_content = "Everyone's been here the whole time.",
  ui_story_5055_50551901_22_dialog_content = "Eve!",
  ui_story_5055_50551901_23_dialog_content = "Eve...",
  ui_story_5055_50551901_24_dialog_content = "Eve, Eve, Eve...",
  ui_story_5055_50551901_25_dialog_content = "Eve!",
  ui_story_5055_50551901_26_dialog_content = "Brother...",
  ui_story_5055_50551901_27_dialog_content = "My family, my friends, my longing for the real world...",
  ui_story_5055_50551901_28_dialog_content = "I'm getting it back, getting it all back!",
  ui_story_5055_50551901_29_dialog_content = "But the present me isn't complete. I've destroyed parts of me.",
  ui_story_5055_50551901_30_dialog_content = "I can't leave and see you again...",
  ui_story_5055_50551901_31_dialog_content = "Yes, you can. You always could.",
  ui_story_5055_50551901_32_dialog_content = "Huh?",
  ui_story_5055_50551901_33_dialog_content = "You're back! I thought you were totally gone!",
  ui_story_5055_50551901_34_dialog_content = "You can feel fear again, can't you?",
  ui_story_5055_50551901_35_dialog_content = "After what I did to you... Thank you for coming back to me.",
  ui_story_5055_50551901_36_dialog_content = "But I see I've never could eliminate my anxiety and fear.",
  ui_story_5055_50551901_37_dialog_content = "Should I be grateful for not being able to conquer them?",
  ui_story_5055_50551901_38_dialog_content = "You're not only afraid of losing control of your power, you're afraid of many other things.",
  ui_story_5055_50551901_39_dialog_content = "Bugs that bite, sharp stingers, dark places, brother getting hurt, no one paying attention to you...",
  ui_story_5055_50551901_40_dialog_content = "Stop, just stop! Must you keep going?",
  ui_story_5055_50551901_41_dialog_content = "But that's okay. That makes you who you are... The real you, the real us.",
  ui_story_5055_50551901_42_dialog_content = "Only those who understood love and had something to love could feel fear and sorrow.",
  ui_story_5055_50551901_43_dialog_content = "The power I have now comes from the love in your heart.",
  ui_story_5055_50551901_44_dialog_content = "Are you going away again?",
  ui_story_5055_50551901_45_dialog_content = "I'm you. I'm a part of us. I'll never go away.",
  ui_story_5055_50551901_46_dialog_content = "But I'll become you, turning us into me and giving you the strength to move forward.",
  ui_story_5055_50551901_47_dialog_content = "Can we... Can I get out of here now?",
  ui_story_5055_50551901_48_dialog_content = "Yes. We'll wake up in the real world very soon.",
  ui_story_5055_50551901_49_dialog_content = "I have another question! PlayerName said they needed my help.",
  ui_story_5055_50551901_50_dialog_content = "You know the reality better than I do, so tell me how I can help after I wake up?",
  ui_story_5055_50551901_51_dialog_content = "You're already helping to control the storm. But there's one thing everyone wants from you.",
  ui_story_5055_50551901_52_dialog_content = "They want you to live a happy, carefree life.",
  ui_story_5055_50551901_53_dialog_content = "It's okay if you're immature, not strong enough, or need a lot of practice to master your power.",
  ui_story_5055_50551901_54_dialog_content = "The key is to persevere and live.",
  ui_story_5055_50551901_55_dialog_content = "Wake up! Eve!",
  ui_story_5055_50551901_56_dialog_content = "Listen, someone's waiting for you.",
  ui_story_5055_50551901_57_dialog_content = "That's PlayerName, brother, Dawn, and the Rediesel Wrench guys...",
  ui_story_5055_50551901_58_dialog_content = "They need me!",
  ui_story_5055_50551901_59_dialog_content = "I'm afraid of many things in reality out there, but there are a lot of things I love, too!",
  ui_story_5055_50551901_60_dialog_content = "Love is much more precious than hate.",
  ui_story_5055_50551901_61_dialog_content = "I have people I love, places I love, so...",
  ui_story_5055_50551901_62_dialog_content = "I shall live on!",
  ui_story_5055_50551901_63_dialog_content = "Very soon, I'll open my eyes...",
  ui_story_5055_50551901_64_dialog_content = "Then I'll take my first breath with everything I got and cherish my life.",
  ui_story_5055_50551901_65_dialog_content = "I will live, as well as those who love me!",
  ui_story_5055_50559901_1_dialog_content = "This piece...",
  ui_story_5055_50559901_2_dialog_content = "<color=#e8d9bb>It seems this piece of paper was torn out of a picture book.</color>",
  ui_story_5055_50559901_3_dialog_content = "<color=#e8d9bb>It vaguely depicts the head of a mysterious woman wearing a white coat.</color>",
  ui_story_5055_50559901_4_dialog_content = "Isn't this the part that's missing from my picture book! The shape fits... but why does the color seem off...?",
  ui_story_5055_50559901_5_dialog_content = "Let me see what's on it...",
  ui_story_5055_50559901_6_dialog_content = "It's my doctor!",
  ui_story_5055_50559901_7_dialog_content = "It's the nice doctor who cured me! Hehe, well, that makes a lot of sense.",
  ui_story_5055_50559901_8_dialog_content = "After all, it's all thanks to her that I'm free now. I must've wanted to thank her for giving me such a happy home.",
  ui_story_5055_50559901_9_dialog_content = "Come to think of it, I can't even remember if she ever smiled. I think she was either really strict or had a somewhat strange quality about her.",
  ui_story_5055_50559901_10_dialog_content = "Hey, is that what they call... irony?",
  ui_story_5055_50559901_11_dialog_content = "But I feel like she must've smiled at me at least once...",
  ui_story_5055_50559901_12_dialog_content = "Eh, why does it suddenly feel chilly out here in the desert... I should go look for the other pieces while I can!",
  ui_story_5055_50559901_13_dialog_content = "Just wait until I get my hands on whoever tore up this picture book! I can't believe they actually tore the doctor's face out! What's wrong with them?!",
  ui_story_5055_50559901_14_dialog_content = "They tore it so badly that I can't even put it back together again...",
  ui_story_5055_50559901_15_dialog_content = "Hang on, now that I look at this tear properly, it looks like there's a row of tooth marks here...",
  ui_story_5055_50559901_16_dialog_content = "Could it be that it wasn't the shadow but some kind of critter gnawing this piece off?",
  ui_story_5055_50559901_17_dialog_content = "Erm, but if it was just a critter, then I'll just drop it. I can't exactly go chasing after an animal...",
  ui_story_5055_50559902_1_dialog_content = "<color=#e8d9bb>Upon the piece of paper is the image of a ceramic flower pot containing a small mound of soil.</color>",
  ui_story_5055_50559902_2_dialog_content = "It's a piece of paper with an empty flower pot on it... It's exactly the same as the one I've got at home!",
  ui_story_5055_50559902_3_dialog_content = "Except this one's empty... There's nothing growing in it.",
  ui_story_5055_50559902_4_dialog_content = "If only I had the right seed for it...",
  ui_story_5055_50559902_5_dialog_content = "Was this piece of paper torn from my picture book too?",
  ui_story_5055_50559902_6_dialog_content = "It looks like it's about the right size, but the picture's all wrong.",
  ui_story_5055_50559902_7_dialog_content = "It should be the face of someone important to me here...",
  ui_story_5055_50559902_8_dialog_content = "But I can't remember a thing. My head's as empty as this flower pot!",
  ui_story_5055_50559902_9_dialog_content = "Forgetting the people most important to me... it's just like a flower pot missing its flowers.",
  ui_story_5055_50559902_10_dialog_content = "All I need to do is think of a way to find what I'm looking for...",
  ui_story_5055_50559903_1_dialog_content = "<color=#e8d9bb>A mysterious white creature!</color>",
  ui_story_5055_50559903_2_dialog_content = "Uh—What's this thing? I've never seen a white toad before!",
  ui_story_5055_50559903_3_dialog_content = "I just adore toads, and a white one like this must be super rare!",
  ui_story_5055_50559903_4_dialog_content = "Hmm... but it doesn't seem all that much like a toad—it's so small and so pretty. Maybe it's actually a frog...",
  ui_story_5055_50559903_5_dialog_content = "You're going the wrong way, little froggy, the lake's that way! Hop around in the Rediesel Desert for too long and you might dry up.",
  ui_story_5055_50559903_6_dialog_content = "I know another place where there's water, if you don't mind coming along with me...",
  ui_story_5055_50559903_7_dialog_content = "Honestly, why would you ever come to such a dry, dark place...?",
  ui_story_5055_50559903_8_dialog_content = "... To find... Eve...",
  ui_story_5055_50559903_9_dialog_content = "?!",
  ui_story_5055_50559903_10_dialog_content = "Did I hear something just now... Was it my imagination?",
  ui_story_5055_50559904_1_dialog_content = "<color=#e8d9bb>A toy with a distinctive appearance. Though its basic design seems ordinary enough, it bears the hallmarks of exquisite craftsmanship.</color>",
  ui_story_5055_50559904_2_dialog_content = "This toy... looks like that red-haired doggy...",
  ui_story_5055_50559904_3_dialog_content = "... Did you come here to join me in that doggy's place?",
  ui_story_5055_50559904_4_dialog_content = "It's a bit dirty, but holding it makes me feel so warm inside, like embracing someone close to me...",
  ui_story_5055_50559904_5_dialog_content = "I suddenly feel a little homesick.",
  ui_story_5055_50559904_6_dialog_content = "This is strange, isn't my home somewhere really, really close by?",
  ui_story_5055_50559904_7_dialog_content = "But why is it that I still miss my family so much...?",
  ui_story_5055_50559904_8_dialog_content = "I miss having those big warm arms wrapped around me...",
  ui_story_5055_50559905_1_dialog_content = "<color=#e8d9bb>An item left behind by the white creature!</color>",
  ui_story_5055_50559905_2_dialog_content = "I thought I saw a pale little creature jump out in front of me just now...",
  ui_story_5055_50559905_3_dialog_content = "Did it leave this?",
  ui_story_5055_50559905_4_dialog_content = "What a gorgeous little treasure! Let me see, is this a super tiny hairband?",
  ui_story_5055_50559905_5_dialog_content = "It seems kinda familiar... Where have I seen this before...?",
  ui_story_5055_50559905_6_dialog_content = "... I'm here... Eve...",
  ui_story_5055_50559905_7_dialog_content = "I really heard something! But it feels like it's coming from such a strange place...",
  ui_story_5055_50559905_8_dialog_content = "Like... someone's calling out to me from the inside...",
  ui_story_5055_50559906_1_dialog_content = "<color=#e8d9bb>A piece of paper with a colossal wrench pattern, exuding an air of might and style.</color>",
  ui_story_5055_50559906_2_dialog_content = "... Is this... another one of my paintings? This one looks like a wrench.",
  ui_story_5055_50559906_3_dialog_content = "I remember when my brother got me my first paintbrush... The first thing he taught me to paint was this wrench.",
  ui_story_5055_50559906_4_dialog_content = "He got so mad at himself when his painting didn't turn out like he wanted, so he scrunched the page up in a huff...",
  ui_story_5055_50559906_5_dialog_content = "But when I painted one better than his, he looked so proud and said he wasn't surprised I could do it, seeing as how I'm his sister.",
  ui_story_5055_50559906_6_dialog_content = "...",
  ui_story_5055_50559906_7_dialog_content = "... Brother...",
  ui_story_5055_50559907_1_dialog_content = "<color=#e8d9bb>A lonely seed, like a solemn vow, awaits discovery in the corner.</color>",
  ui_story_5055_50559907_2_dialog_content = "Is this... a flower seed?!",
  ui_story_5055_50559907_3_dialog_content = "I remember what your flowers look like!",
  ui_story_5055_50559907_4_dialog_content = "This is your seed, right? The little friend I lost in the fire...",
  ui_story_5055_50559907_5_dialog_content = "Thank you. You were always there when I needed you most.",
  ui_story_5055_50559907_6_dialog_content = "But what are you doing in a place like this?! You're gonna get burned!",
  ui_story_5055_50559907_7_dialog_content = "Let me give you a new home—somewhere I can keep you safe! I won't let anything bad happen to you, I promise!",
  ui_story_5055_50559907_8_dialog_content = "I think that, a long time ago, I made another promise...",
  ui_story_5055_50559907_9_dialog_content = "I have to remember!",
  ui_story_5055_50559908_1_dialog_content = "<color=#e8d9bb>Put the tiny hairband on the little white creature!</color>",
  ui_story_5055_50559908_2_dialog_content = "<color=#e8d9bb>The frog appears to have grown larger after the hairband is placed on it, and begins to emit a faint glow.</color>",
  ui_story_5055_50559908_3_dialog_content = "It's a perfect fit! It might just be a basic little accessory...",
  ui_story_5055_50559908_4_dialog_content = "But it sort of makes you seem more refined, like the frog prince in that fairy tale picture book.",
  ui_story_5055_50559908_5_dialog_content = "(I bet if I dressed it up properly, it'd make such a handsome prince!)",
  ui_story_5055_50559908_6_dialog_content = "... Hey, where do you think you're going?!",
  ui_story_5055_50559908_7_dialog_content = "It's not safe out there! Don't leave!",
  ui_story_5055_50559908_8_dialog_content = "... Don't worry. I know you'd never hurt me.",
  ui_story_5055_50559908_9_dialog_content = "What?!",
  ui_story_5055_50559908_10_dialog_content = "... Your struggle... so hard. Let me do something for you too!",
  ui_story_5055_50559908_11_dialog_content = "So that you don't have to go through all this alone!",
  ui_story_5055_50559909_1_dialog_content = "<color=#e8d9bb>The little white creature's Colossus!</color>",
  ui_story_5055_50559909_2_dialog_content = "This is... I remember! It flies through the sky, majestic and free...",
  ui_story_5055_50559909_3_dialog_content = "Have I ever been inside it?",
  ui_story_5055_50559909_4_dialog_content = "... I remember a shining window, with a deep blue expanse outside.",
  ui_story_5055_50559909_5_dialog_content = "I remember someone giving me food and saying kind words to me.",
  ui_story_5055_50559909_6_dialog_content = "I started running around inside this thing... I hadn't felt that good in such a long time, and then...",
  ui_story_5055_50559909_7_dialog_content = "Uh—",
  ui_story_5055_50559909_8_dialog_content = "Then you set off on a journey.",
  ui_story_5055_50559909_9_dialog_content = "You're—?!",
  ui_story_5055_50559909_10_dialog_content = "... Although you faced many unexpected adventures along the way, you were determined to fulfill an important promise.",
  ui_story_5055_50559909_11_dialog_content = "... Now, you're finally so close to fulfilling that promise, and there are many people waiting for you...",
  ui_story_5055_50559910_1_dialog_content = "<color=#e8d9bb>The toy sees the wrench in the painting and leaps into the torn page with unbridled enthusiasm.</color>",
  ui_story_5055_50559910_2_dialog_content = "<color=#e8d9bb>The toy and the wrench radiate a warm light, like the glow of the morning sun. Eve rubs her eyes, and a familiar face appears in the image.</color>",
  ui_story_5055_50559910_3_dialog_content = "Ahh! It's... It's my brother!",
  ui_story_5055_50559910_4_dialog_content = "Finally... I finally remember my brother's face!",
  ui_story_5055_50559910_5_dialog_content = "... E... Eve!",
  ui_story_5055_50559910_6_dialog_content = "... It's my brother's voice! Where's it coming from...?",
  ui_story_5055_50559910_7_dialog_content = "His burning desire has manifested itself. Although you can hear his voice, he cannot sense your presence.",
  ui_story_5055_50559910_8_dialog_content = "Eve!",
  ui_story_5055_50559910_9_dialog_content = "I'm sorry for everything that happened before. I didn't pay enough attention to how you really felt... because I thought I was protecting you, but... I didn't understand how much pain you were in...",
  ui_story_5055_50559910_10_dialog_content = "I'm a terrible brother.",
  ui_story_5055_50559910_11_dialog_content = "No, brother, I was so stubborn. I just... I can't stand the way I am anymore. That's why...",
  ui_story_5055_50559910_12_dialog_content = "A storm's coming, but don't worry—I promise I'll protect you.",
  ui_story_5055_50559910_13_dialog_content = "No... Sinsa, just run, quickly...",
  ui_story_5055_50559910_14_dialog_content = "I'm gonna tear a hole in this storm with my hands and drag you out of there! I'm bringing you home!",
  ui_story_5055_50559910_15_dialog_content = "Then, if you think you can forgive me one day, just wake up...",
  ui_story_5055_50559910_16_dialog_content = "... Home's just the way you left it. All your favorite dolls and your paintings are waiting for you in your room...",
  ui_story_5055_50559910_17_dialog_content = "...",
  ui_story_5055_50559910_18_dialog_content = "Eve, I really miss you...",
  ui_story_5055_50559910_19_dialog_content = "... Sinsa... I miss you too...",
  ui_story_5055_50559911_1_dialog_content = "<color=#e8d9bb>A flower seed falls into the empty pot in the picture book, and a dawn flower blooms on the page.</color>",
  ui_story_5055_50559911_2_dialog_content = "<color=#e8d9bb>The flower blooms with a shining light, as dazzling as the dawn. Eve rubs her eyes, and a familiar face appears on the page.</color>",
  ui_story_5055_50559911_3_dialog_content = "Dawn! I... I remember! It's the face of my friend—the one who's always been there for me... It's Dawn!",
  ui_story_5055_50559911_4_dialog_content = "... Eve.",
  ui_story_5055_50559911_5_dialog_content = "... Who's voice is that? Dawn... Dawn! Is that you?",
  ui_story_5055_50559911_6_dialog_content = "Her burning desire has manifested itself. You can hear her voice, but your words cannot be conveyed to her.",
  ui_story_5055_50559911_7_dialog_content = "... Eve...",
  ui_story_5055_50559911_8_dialog_content = "... Seeing you like this... It reminds me of the day we met...",
  ui_story_5055_50559911_9_dialog_content = "In that cold infirmary, our bodies were covered in sensors and tubes...",
  ui_story_5055_50559911_10_dialog_content = "I... I'm not as dependable as you thought...",
  ui_story_5055_50559911_11_dialog_content = "In the darkness, and through the fear, all I could do was clench my muscles and brace for the pain... That's why I ignored you back then, and why you almost got me wrong.",
  ui_story_5055_50559911_12_dialog_content = "No, you ARE dependable, Dawn! And you're the bravest person I know...",
  ui_story_5055_50559911_13_dialog_content = "That infirmary was like a cage, and you were the only one who dared to challenge our captor head-on.",
  ui_story_5055_50559911_14_dialog_content = "It was soon after that I realized you weren't at all bad—you just like looking at people with that fierce look on your face.",
  ui_story_5055_50559911_15_dialog_content = "Completely, utterly, not horrible.",
  ui_story_5055_50559911_16_dialog_content = "... I loved listening to your stories. Your voice, your words... They carried the beauty of the world I longed to see and laid it out before my eyes.",
  ui_story_5055_50559911_17_dialog_content = "... Although it was a bit awkward whenever you forgot what was supposed to come next...",
  ui_story_5055_50559911_18_dialog_content = "But the stories themselves were never as important as simply having you by my side...",
  ui_story_5055_50559911_19_dialog_content = "You gave the flower water, you gave me a name...",
  ui_story_5055_50559911_20_dialog_content = "I really like this name... Dawn... Dawn...",
  ui_story_5055_50559911_21_dialog_content = "So, you need to wake up soon, okay?",
  ui_story_5055_50559911_22_dialog_content = "Remember the promise we made—to watch the moment the dawn flower blooms, together...",
  ui_story_5055_50559911_23_dialog_content = "Dawn, I still remember... I remember everything... *sob* It was awful.",
  ui_story_5055_50559911_24_dialog_content = "Dawn's still standing there in the dawn flower field waiting for me to find her!",
  ui_story_5055_50559912_1_dialog_content = "<color=#e8d9bb>The white frog prince jumps into the picture and sits squarely on the Colossus.</color>",
  ui_story_5055_50559912_2_dialog_content = "<color=#e8d9bb>The Colossus's white wings extend in an arc, like a barrage of meteors reaching for the horizon. Eve rubs her eyes, and a familiar face appears on the page.</color>",
  ui_story_5055_50559912_3_dialog_content = "... I know you!",
  ui_story_5055_50559912_4_dialog_content = "Tail Street, Eclipsites, Brother, Dawn, and the people who faced these memories with me...",
  ui_story_5055_50559912_5_dialog_content = "PlayerName, I remember you!",
  ui_story_5055_50559912_6_dialog_content = "It was you all along, constantly speaking to me, pushing me forward through this dream with information from the outside world...",
  ui_story_5055_50559912_7_dialog_content = "Accompanying me as I sifted through my past to find the pain, the anger, the fear within me...",
  ui_story_5055_50559912_8_dialog_content = "Even if everyone's cursed in the deepest part of this twisted dream...",
  ui_story_5055_50559912_9_dialog_content = "Where brother's been turned into a big dog, Dawn's been turned into a flower, and a wicked witch turned you into a little frog...",
  ui_story_5055_50559912_10_dialog_content = "You still found me! You couldn't let me face this nightmare alone!",
  ui_story_5055_50559912_11_dialog_content = "You're my frog prince, aren't you?",
  ui_story_5055_50559912_12_dialog_content = "... If that's true, then let me ask you something.",
  ui_story_5055_50559912_13_dialog_content = "Your chaotic memories have been stilled, and your prince's curse has been lifted.",
  ui_story_5055_50559912_14_dialog_content = "Surely the princess wants to break free from the witch's curse and face her true self too, right?",
  ui_story_5055_50559912_15_dialog_content = "My true self...",
